import { H } from 'harness-dsl';
import { z } from 'zod';
import * as claudeCode from 'harness-dsl/claude-code';
import * as anthropic from 'harness-dsl/anthropic';
import * as sqlite from 'harness-dsl/sqlite';
import * as jsonl from 'harness-dsl/jsonl';
import * as ssh from 'harness-dsl/ssh';
import * as markdown from 'harness-dsl/markdown';

const sourceSystem = z.enum(['crm', 'billing', 'inventory', 'web']);

const NightlyLoad = H.kind('nightly-load')
  .data(z.object({
    source: sourceSystem,
    night: z.string(),
    summary: z.string().optional(),
    drift: z.number().optional()
  }))
  .states(
    H.state('load-scheduled', 'pending'),
    H.state('extracting', 'active'),
    H.state('validating', 'active'),
    H.state('summarizing', 'active'),
    H.state('awaiting-approval', 'active'),
    H.state('loading', 'active'),
    H.state('verifying', 'active'),
    H.state('loaded', 'terminal', 'success'),
    H.state('loaded-with-warnings', 'terminal', 'success'),
    H.state('load-rejected', 'terminal', 'neutral'),
    H.state('load-expired', 'terminal', 'neutral'),
    H.state('load-failed', 'terminal', 'failure')
  )
  .failsTo('load-failed');

const approverTaste = H.library(
  'approver-emphasis',
  H.memory('approver-taste', 'taste'),
  jsonl.memory('.harness/approver-taste.jsonl')
);

const warehouse = ssh.host('warehouse', {
  address: 'warehouse.internal',
  user: 'etl',
  key: H.env('WAREHOUSE_SSH_KEY'),
  slots: 2
});

const job = z.object({ source: sourceSystem, night: z.string() });

const extract = H.command('extract')
  .input(job)
  .argv(({ source, night }) => ['/opt/etl/extract.sh', source, night])
  .on(warehouse);

const validate = H.command('validate')
  .input(job)
  .output(z.object({ passed: z.boolean(), report: z.string(), anomalies: z.array(z.string()) }))
  .argv(({ source, night }) => ['/opt/etl/validate.sh', source, night])
  .on(warehouse);

const load = H.command('load')
  .input(job)
  .argv(({ source, night }) => ['/opt/etl/load.sh', source, night])
  .on(warehouse);

const verify = H.command('verify')
  .input(job)
  .output(z.object({ drift: z.number(), tolerable: z.boolean() }))
  .argv(({ source, night }) => ['/opt/etl/verify.sh', source, night])
  .on(warehouse);

const exponentialBackoff = H.policy.retry('three-retries-exponential', ({ failures }) =>
  failures > 3 ? 'stop' : { retryInMs: 60_000 * 2 ** (failures - 1) });

const noLaneRetry = H.policy.retry('no-lane-retry', () => 'stop');

const summarizerRole = H.role('anomaly-summarizer')
  .input(z.object({ source: z.string(), report: z.string(), anomalies: z.array(z.string()) }))
  .output(z.object({ summary: z.string() }))
  .prompt((input) => `Summarise, in plain language for the approver, the anomalies in tonight's ${input.source} extract.\n\nValidation report:\n${input.report}\n\nAnomalies:\n- ${input.anomalies.join('\n- ')}`);

const summarizer = H.agent('anomaly-summarizer', summarizerRole)
  .model(anthropic.model('claude-sonnet-4-5'))
  .recalls(approverTaste);

const validationReview = H.halt('validation-review', z.object({ action: z.enum(['continue', 'reject']) }));
const loadApproval = H.halt('load-approval', z.object({ approve: z.boolean(), note: z.string().optional() }));

const nightlyWork = H.flow('nightly-load-run')
  .for(NightlyLoad)
  .does(async (ctx) => {
    const target = { source: ctx.unit.data.source, night: ctx.unit.data.night };

    await ctx.move('extracting');
    const extracted = await ctx.run(extract, target, { retry: exponentialBackoff });
    if (!extracted.ok) return ctx.fail(`extract: ${extracted.error}`);

    await ctx.move('validating');
    const validation = await ctx.run(validate, target);
    if (!validation.ok) return ctx.fail(`validate: ${validation.error}`);
    if (!validation.value.passed) {
      const review = await ctx.halt(validationReview, validation.value.report);
      if (review.action === 'reject') return 'load-rejected';
    }

    await ctx.move('summarizing');
    const summarized = await ctx.run(summarizer, {
      source: target.source,
      report: validation.value.report,
      anomalies: validation.value.anomalies
    });
    if (!summarized.ok) return ctx.fail(`summary: ${summarized.error}`);
    await ctx.update({ summary: summarized.value.summary });

    await ctx.move('awaiting-approval');
    const approval = await ctx.halt(loadApproval, summarized.value.summary);
    if (!approval.approve) return 'load-rejected';

    await ctx.move('loading');
    const loaded = await ctx.run(load, target, { retry: exponentialBackoff });
    if (!loaded.ok) return ctx.fail(`load: ${loaded.error}`);

    await ctx.move('verifying');
    const verified = await ctx.run(verify, target);
    if (!verified.ok) return ctx.fail(`verify: ${verified.error}`);
    if (verified.value.drift === 0) return 'loaded';
    if (!verified.value.tolerable) return ctx.fail(`verify: drift ${verified.value.drift} beyond tolerance`);
    await ctx.update({ drift: verified.value.drift });
    return 'loaded-with-warnings';
  });

const nightlySchedule = H.clock('nightly-0200', NightlyLoad, { daily: '02:00' }, ({ now }) => {
  const night = now.toISOString().slice(0, 10);
  return sourceSystem.options.map((source) => NightlyLoad.create({ source, night }, `${source}-${night}`));
});

const loadLane = H.lane('nightly-loads', NightlyLoad)
  .handler(nightlyWork)
  .suppliers(nightlySchedule)
  .store(sqlite.store(NightlyLoad, '.harness/nightly-loads.db'))
  .retry(noLaneRetry);

const approvalExpiry = H.trigger(
  'approval-expires-at-0900',
  H.on.deadline(NightlyLoad, (data) => new Date(`${data.night}T09:00:00`), ['awaiting-approval']),
  (_event, act) => act.move('load-expired')
);

const summaryPool = H.pool('summary-accounts', [
  { account: anthropic.account('etl-api', { apiKey: H.env('ANTHROPIC_API_KEY') }), share: 1 }
]);

export default H.harness('nightly-data')
  .ledger(sqlite.ledger('.harness/nightly-data.db'))
  .lanes(loadLane)
  .pools(summaryPool)
  .triggers(approvalExpiry)
  .clients(claudeCode.supervisor({
    grants: [H.ops.readWork, H.ops.resolveHalts, H.ops.readMemory, H.ops.writeMemory, H.ops.readTelemetry]
  }))
  .observers(markdown.board('BOARD.md'), markdown.telemetry('TELEMETRY.md'));

=== END ===

=== FILE: scenarios/06-content-taste.ts ===
import { z } from 'zod';
import { H } from 'harness-dsl';
import type { Metrics, Model, ModelChoice } from 'harness-dsl';
import * as anthropic from 'harness-dsl/anthropic';
import * as claudeCode from 'harness-dsl/claude-code';
import * as http from 'harness-dsl/http';
import * as jsonl from 'harness-dsl/jsonl';
import * as markdown from 'harness-dsl/markdown';
import * as shell from 'harness-dsl/shell';
import * as sqlite from 'harness-dsl/sqlite';

const section = z.enum(['news', 'sports', 'opinion', 'culture']);

const submitted = H.state('submitted', 'pending');
const reviewing = H.state('reviewing', 'active');
const returned = H.state('returned', 'waiting');
const accepted = H.state('accepted', 'terminal', 'success');
const withdrawn = H.state('withdrawn', 'terminal', 'neutral');

const Draft = H.kind('draft')
  .data(z.object({ title: z.string(), body: z.string(), section, editorNotes: z.string().optional() }))
  .states(submitted, reviewing, returned, accepted, withdrawn);

const editorialTaste = H.memory('editorial-taste', 'taste');
const factCheckLessons = H.memory('fact-check-lessons', 'experience');
const houseTaste = H.library('house-taste', editorialTaste, jsonl.memory('memory/taste.jsonl'));
const factLessons = H.library('fact-lessons', factCheckLessons, jsonl.memory('memory/fact-lessons.jsonl'));

const reviewer = H.role('reviewer')
  .input(z.object({ title: z.string(), body: z.string(), section, findings: z.array(z.string()) }))
  .output(z.object({ critique: z.string(), points: z.array(z.string()) }))
  .prompt(input => `Critique the ${input.section} draft "${input.title}".\n\nFact-check findings:\n${input.findings.join('\n')}\n\n${input.body}`)
  .intents(['read']);

const incumbentA = anthropic.model('claude-opus-4-1');
const incumbentB = anthropic.model('claude-sonnet-4-5');
const challenger = anthropic.model('claude-haiku-4-5');

const editorDecision = H.halt('editor-decision', z.object({
  action: z.enum(['accept', 'return']),
  notes: z.string(),
  actedOnA: z.boolean(),
  actedOnB: z.boolean(),
}));

const decisions = editorDecision.resolved();
const actedOnA = editorDecision.resolved({ actedOnA: true });
const actedOnB = editorDecision.resolved({ actedOnB: true });

function weakerReviewer(metrics: Metrics): 'a' | 'b' | null {
  const a = metrics.rateBy({ among: decisions, count: actedOnA, by: { model: reviewerA }, days: 60 }).get(incumbentA);
  const b = metrics.rateBy({ among: decisions, count: actedOnB, by: { model: reviewerB }, days: 60 }).get(incumbentB);
  if (a.samples < 50 || b.samples < 50 || a.value === null || b.value === null || a.value === b.value) return null;
  return a.value < b.value ? 'a' : 'b';
}

function pickReviewerA({ metrics }: ModelChoice): Model {
  return weakerReviewer(metrics) === 'a' ? challenger : incumbentA;
}

function pickReviewerB({ metrics }: ModelChoice): Model {
  return weakerReviewer(metrics) === 'b' ? challenger : incumbentB;
}

const reviewerA = H.agent('reviewer-a', reviewer)
  .model(H.policy.model('reviewer-a-model', pickReviewerA))
  .recalls(houseTaste, factLessons);

const reviewerB = H.agent('reviewer-b', reviewer)
  .model(H.policy.model('reviewer-b-model', pickReviewerB))
  .recalls(houseTaste, factLessons);

const local = shell.local('local', { slots: 4 });

const factCheck = H.command('fact-check')
  .input(z.object({ draft: z.string(), body: z.string() }))
  .output(z.object({
    findings: z.array(z.string()),
    repeatMistakes: z.array(z.object({ rule: z.string(), because: z.string() })),
  }))
  .argv(input => ['fact-check', '--draft', input.draft, '--text', input.body])
  .on(local);

const mergeCritiques = H.command('merge-critiques')
  .input(z.object({ a: z.string(), b: z.string() }))
  .output(z.object({ summary: z.string() }))
  .argv(input => ['merge-critiques', '--a', input.a, '--b', input.b])
  .on(local);

const reviewFlow = H.flow('draft-review').for(Draft).does(async ctx => {
  await ctx.move('reviewing');
  const { title, body } = ctx.unit.data;
  const draftSection = ctx.unit.data.section;
  const scope = { resources: [`section:${draftSection}`] };

  const facts = await ctx.run(factCheck, { draft: ctx.unit.key, body });
  if (!facts.ok) return ctx.fail(facts.error);
  for (const lesson of facts.value.repeatMistakes) {
    await ctx.remember(factLessons, { text: lesson.rule, because: lesson.because, when: { kinds: [Draft] } });
  }

  const input = { title, body, section: draftSection, findings: facts.value.findings };
  const a = await ctx.run(reviewerA, input, { scope });
  if (!a.ok) return ctx.fail(a.error);
  const b = await ctx.run(reviewerB, input, { scope });
  if (!b.ok) return ctx.fail(b.error);

  const merged = await ctx.run(mergeCritiques, { a: a.value.critique, b: b.value.critique });
  if (!merged.ok) return ctx.fail(merged.error);

  const decision = await ctx.halt(editorDecision, merged.value.summary);
  if (decision.action === 'accept') return 'accepted';
  await ctx.update({ editorNotes: decision.notes });
  return 'returned';
});

const cmsHeaders = { authorization: H.env('CMS_TOKEN') };

const cms = http.poll(Draft, {
  url: 'https://cms.example.com/api/drafts?review=pending',
  every: { minutes: 5 },
  headers: cmsHeaders,
  body: z.object({
    drafts: z.array(z.object({
      id: z.string(),
      title: z.string(),
      body: z.string(),
      section,
      status: z.enum(['new', 'revised', 'withdrawn']),
    })),
  }),
  read: body => body.drafts.map(draft =>
    draft.status === 'new'
      ? Draft.create({ title: draft.title, body: draft.body, section: draft.section }, draft.id)
      : draft.status === 'revised'
        ? Draft.update(draft.id, { patch: { body: draft.body }, state: 'submitted' })
        : Draft.update(draft.id, { state: 'withdrawn' })),
});

const cmsStore = http.store(Draft, {
  url: 'https://cms.example.com/api/drafts',
  headers: cmsHeaders,
  stateField: 'review_status',
});

const drafts = H.lane('drafts', Draft).handler(reviewFlow).suppliers(cms).store(cmsStore).wip(3);

const notesBecomeTaste = H.trigger('notes-become-taste', H.on.enters(Draft, 'returned'), (event, act) => {
  const notes = event.unit.data.editorNotes;
  return notes
    ? act.remember(houseTaste, {
        text: notes,
        because: `the editor returned "${event.unit.data.title}" with this note`,
        when: { kinds: [Draft], resources: [`section:${event.unit.data.section}`] },
        status: 'candidate',
      })
    : [];
});

const pool = H.pool('api', [{ account: anthropic.account('anthropic-api', { apiKey: H.env('ANTHROPIC_API_KEY') }), share: 1 }]);

export const harness = H.harness('content-review')
  .ledger(sqlite.ledger('.harness/content.sqlite'))
  .lanes(drafts)
  .pools(pool)
  .triggers(notesBecomeTaste)
