      return ctx.count(experiments, 'active') < limit;
    }))
  .clients(supervisor)
  .observers(markdown.board({ path: 'lifecycles/BOARD.md' }), markdown.telemetry({ path: 'lifecycles/TELEMETRY.md' }));

