  .input(z.object({ negotiationId: z.string(), offer: z.string(), accept: z.boolean() }))
  .argv((input) => ['procurement', 'send', input.negotiationId, input.accept ? '--accept' : '--offer', input.offer])
  .runner(localRunner);

