  .handler(epicFlow, {
    opens: Decomposing,
    ends: { completed: Completed, stalled: Stalled },
    spawns: {
      features: child => features.unit({
        attributes: {
          issueId: `${child.epicId}/${child.title}`,
          title: child.title,
          description: child.description,
          priority: 2,
          epicId: child.epicId,
        },
      }),
    },
  })
  .wip(1);

